// 재출금 안내도 출금 예정 알림처럼 계약·날짜 단위 키다(1.9.0부터).
// TODO: 하루 두 번째 재출금 안내까지 막히는데 아직 날짜 단위여야 하나?
export function reminderKey(kind: ReminderKind, autopayId: string, dueAt: LocalDateTime): string {
